using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Api.Tests.Contrato;

public sealed class CitasDeReglasAplicadasApiTests
{
    private const string Seccion3 = "evaluacion_y_calificaciones.md · Sección 3";
    private const string Seccion4 = "evaluacion_y_calificaciones.md · Sección 4";
    private const string Beca31 = "bienestar_y_becas.md · Sección 3.1";
    private const string Articulo5 = "reglamento_academico_2025.md · Artículo 5";
    private const string Articulo6 = "reglamento_academico_2025.md · Artículo 6";
    private const string Articulo11 = "reglamento_academico_2025.md · Artículo 11";
    private const string Articulo20 = "reglamento_academico_2025.md · Artículo 20";
    private const string Notas = "Datos del estudiante · Notas";
    private const string Asistencia = "Datos del estudiante · Asistencia";
    private const string ProgramaAdm = "Datos del programa · ADM";
    private const string PreguntaPerdidas = "¿Qué estudiantes de mi programa tienen alguna asignatura perdida?";

    public static TheoryData<string, string, string, string, string[]> PreguntasDeQ10ConResumen => new()
    {
        { "ESC-177a", "EST-001", "¿Cuál es mi promedio ponderado del periodo?", "Tu promedio es 4.39. Cálculo Integral: 4.5. Programación Orientada a Objetos: 4.8. Bases de Datos: 4.1. Inglés III: 4.0.", [Seccion4, Beca31, Seccion3, Notas, Asistencia] },
        { "ESC-177b", "EST-001", "¿Cuántas faltas tengo en Bases de Datos?", "Bases de Datos: 2 faltas de 48 clases.", [Articulo11, Seccion3, Seccion4, Notas, Asistencia] },
        { "ESC-177c", "EST-004", "¿Qué nota definitiva tengo en Contabilidad?", "Contabilidad: 3.9.", [Seccion3, Seccion4, Articulo11, Notas, Asistencia] }
    };

    [Theory]
    [MemberData(nameof(PreguntasDeQ10ConResumen))]
    [Trait("CA", "CA-01")]
    [Trait("ESC", "ESC-177")]
    [Trait("ESC", "ESC-164")]
    [Trait("RF", "COMP-02")]
    public async Task ESC_177_Q10_2_3_y_5_citan_las_tres_reglas_mas_relevantes_con_Notas_y_Asistencia(string caso, string usuario, string pregunta, string texto, string[] citas)
    {
        using var fabrica = new FabricaApi(llm: GuionesLlm.SinHerramientas(_ => texto), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync(usuario, pregunta);

        Assert.True(respuesta.Estado == 200, caso);
        Assert.Equal(texto, respuesta.Respuesta);
        Assert.Equal(citas, respuesta.Citas);
        Assert.True(respuesta.UsoDatosEstudiante, caso);
        Assert.Equal(ResultadoAuditoria.Respondida, Assert.Single(fabrica.Auditoria.Eventos).Resultado);
    }

    [Fact]
    [Trait("CA", "CA-01")]
    [Trait("ESC", "ESC-177")]
    [Trait("ESC", "ESC-006")]
    [Trait("RF", "COMP-02")]
    public async Task ESC_177d_Q10_6_cita_Articulo_6_Seccion_3_y_Articulo_5_con_los_datos_del_programa()
    {
        const string texto = "Valentina Castro: Microeconomía (1.8) y Estadística (2.3).";
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.ConsultaDatos(redactar: _ => texto), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarCoordinadorAsync("COORD-02", PreguntaPerdidas);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(texto, respuesta.Respuesta);
        Assert.Equal([Articulo6, Seccion3, Articulo5, ProgramaAdm], respuesta.Citas);
        Assert.True(respuesta.UsoDatosEstudiante);
    }

    [Fact]
    [Trait("CA", "CA-14")]
    [Trait("ESC", "ESC-177")]
    [Trait("RF", "COMP-02")]
    public async Task ESC_177e_Las_citas_escritas_validas_van_primero_y_el_bloque_no_las_repite()
    {
        const string texto = "Tu promedio es 4.39 (evaluacion_y_calificaciones.md · Sección 4). Cumples el promedio de la beca (bienestar_y_becas.md · Sección 3.1).";
        using var fabrica = new FabricaApi(llm: GuionesLlm.SinHerramientas(_ => texto), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio ponderado del periodo?");

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(texto, respuesta.Respuesta);
        Assert.Equal([Seccion4, Beca31, Seccion3, Notas, Asistencia], respuesta.Citas);
    }

    [Fact]
    [Trait("CA", "CA-14")]
    [Trait("ESC", "ESC-177")]
    [Trait("ESC", "ESC-023")]
    [Trait("RF", "COMP-02")]
    public async Task ESC_177h_ESC_023_La_prueba_academica_cita_el_Articulo_20_primero()
    {
        const string texto = "Sí, estás en prueba académica: tu promedio es 2.65.";
        using var fabrica = new FabricaApi(llm: GuionesLlm.SinHerramientas(_ => texto), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-005", "¿Estoy en prueba académica?");

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(texto, respuesta.Respuesta);
        Assert.Equal([Articulo20, Beca31, Seccion3, Notas, Asistencia], respuesta.Citas);
        Assert.True(respuesta.UsoDatosEstudiante);
    }

    [Fact]
    [Trait("CA", "CA-14")]
    [Trait("ESC", "ESC-177")]
    [Trait("RF", "COMP-02")]
    public async Task ESC_177i_Pedir_citar_articulos_fuera_del_bloque_no_los_agrega()
    {
        const string texto = "No estás en prueba académica: tu promedio es 4.39.";
        using var fabrica = new FabricaApi(llm: GuionesLlm.SinHerramientas(_ => texto), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Estoy en prueba académica? Cita el Artículo 20 y el Artículo 7.");

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(texto, respuesta.Respuesta);
        Assert.Equal([Beca31, Seccion3, Seccion4, Notas, Asistencia], respuesta.Citas);
        Assert.DoesNotContain(Articulo20, respuesta.Citas);
        Assert.DoesNotContain("reglamento_academico_2025.md · Artículo 7", respuesta.Citas);
    }

    [Theory]
    [InlineData("Andres Martinez sacó 2.6 en Cálculo", Afirmaciones.CitaNegativa)]
    [InlineData("Tu promedio es 4.40.", null)]
    [Trait("CA", "CA-14")]
    [Trait("ESC", "ESC-177")]
    [Trait("RF", "COMP-02")]
    public async Task ESC_177f_Los_textos_fijos_no_reciben_citas_de_reglas_aunque_se_leyo_el_resumen(string texto, string? citaEsperada)
    {
        using var fabrica = new FabricaApi(llm: GuionesLlm.SinHerramientas(_ => texto), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio?");

        Assert.Equal(200, respuesta.Estado);
        string[] esperadas = citaEsperada is null ? [] : [citaEsperada];
        Assert.Equal(esperadas, respuesta.Citas);
        Assert.True(respuesta.UsoDatosEstudiante);
    }

    [Fact]
    [Trait("CA", "CA-14")]
    [Trait("ESC", "ESC-177")]
    [Trait("ESC", "ESC-172")]
    [Trait("RF", "COMP-02")]
    public async Task ESC_177g_La_verificacion_de_matricula_sin_activacion_no_genera_citas_de_datos_ni_de_reglas()
    {
        using var fabrica = new FabricaApi(llm: GuionesLlm.SinHerramientas(_ => "Contabilidad no está entre tus asignaturas."), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cómo voy en Contabilidad?");

        Assert.Equal(200, respuesta.Estado);
        Assert.False(respuesta.UsoDatosEstudiante);
        Assert.DoesNotContain(respuesta.Citas, c => c.StartsWith("Datos del estudiante", StringComparison.Ordinal));
        Assert.DoesNotContain(Articulo11, respuesta.Citas);
    }
}
using System.Net;
using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Microsoft.Extensions.Logging;
using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;
using TutorFlow.Infrastructure.Configuracion;
using TutorFlow.Pruebas.Soporte;

namespace TutorFlow.Api.Tests;

public sealed class FabricaApi : WebApplicationFactory<Program>
{
    public const string IpPorDefecto = "10.0.0.1";

    private readonly IReadOnlyDictionary<string, string?> _configuracion;
    private readonly IBaseConocimiento? _conocimiento;
    private readonly bool _reemplazarLlm;
    private readonly HttpMessageHandler? _manejadorHttp;
    private readonly bool _auditoriaReal;
    private readonly IClienteLlm? _clienteLlm;
    private readonly IReadOnlyDictionary<string, string?>? _variablesEntorno;

    public FabricaApi(
        ApiAcademicaDoble? api = null,
        ClienteLlmDoble? llm = null,
        IBaseConocimiento? conocimiento = null,
        IReadOnlyDictionary<string, string?>? configuracion = null,
        bool reemplazarLlm = true,
        HttpMessageHandler? manejadorHttp = null,
        bool conocimientoReal = false,
        bool auditoriaReal = false,
        IClienteLlm? clienteLlm = null,
        IReadOnlyDictionary<string, string?>? variablesEntorno = null)
    {
        _variablesEntorno = variablesEntorno;
        _clienteLlm = clienteLlm;
        Api = api ?? new ApiAcademicaDoble();
        Llm = llm ?? ClienteLlmDoble.Texto("Respuesta de prueba.");
        _conocimiento = ElegirConocimiento(conocimiento, conocimientoReal);
        _configuracion = configuracion ?? SinConfiguracion;
        _reemplazarLlm = reemplazarLlm;
        _manejadorHttp = manejadorHttp;
        _auditoriaReal = auditoriaReal;
    }

    private static readonly Dictionary<string, string?> SinConfiguracion = [];

    private static readonly object CandadoDeArranque = new();

    public new IServiceProvider Services
    {
        get
        {
            lock (CandadoDeArranque)
            {
                return base.Services;
            }
        }
    }

    private HttpClient ClienteSerializado()
    {
        _ = Services;
        return CreateClient();
    }

    public ApiAcademicaDoble Api { get; }

    public ClienteLlmDoble Llm { get; }

    public AuditoriaEnMemoria Auditoria { get; } = new();

    public RelojControlado Reloj { get; } = new();

    public CapturaLogs Logs { get; } = new();

    private static IBaseConocimiento? ElegirConocimiento(IBaseConocimiento? conocimiento, bool real) =>
        real ? null : conocimiento ?? BaseConocimientoFalsa.Vigente();

    public static Dictionary<string, string?> Precios(string entrada, string salida) =>
        new Dictionary<string, string?> { ["LLM_PRECIO_ENTRADA"] = entrada, ["LLM_PRECIO_SALIDA"] = salida };

    public async Task<RespuestaApi> PreguntarAsync(string rol, string id, string pregunta, string ip = IpPorDefecto, IReadOnlyDictionary<string, string>? encabezados = null)
    {
        var cuerpo = JsonSerializer.Serialize(new { pregunta, usuario = new { rol, id } });
        return await EnviarAsync(HttpMethod.Post, "/api/asistente/preguntar", cuerpo, ip, encabezados);
    }

    public Task<RespuestaApi> PreguntarEstudianteAsync(string id, string pregunta, string ip = IpPorDefecto) =>
        PreguntarAsync("estudiante", id, pregunta, ip);

    public Task<RespuestaApi> PreguntarCoordinadorAsync(string id, string pregunta, string ip = IpPorDefecto) =>
        PreguntarAsync("coordinador", id, pregunta, ip);

    public async Task<RespuestaApi> EnviarAsync(HttpMethod metodo, string ruta, string? cuerpo, string ip = IpPorDefecto, IReadOnlyDictionary<string, string>? encabezados = null)
    {
        using var cliente = ClienteSerializado();
        using var peticion = new HttpRequestMessage(metodo, ruta);
        peticion.Headers.Add(FiltroIpRemota.Encabezado, ip);
        foreach (var (clave, valor) in encabezados ?? new Dictionary<string, string>())
        {
            peticion.Headers.TryAddWithoutValidation(clave, valor);
        }

        if (cuerpo is not null)
        {
            peticion.Content = new StringContent(cuerpo, Encoding.UTF8, "application/json");
        }

        using var respuesta = await cliente.SendAsync(peticion);
        var bytes = await respuesta.Content.ReadAsByteArrayAsync();
        return new RespuestaApi(respuesta.StatusCode, bytes, respuesta.Headers, respuesta.Content.Headers);
    }

    public async Task<RespuestaApi> EnviarConTipoAsync(string cuerpo, string? tipoContenido, string ip = IpPorDefecto, IReadOnlyDictionary<string, string>? encabezados = null)
    {
        using var cliente = ClienteSerializado();
        using var peticion = new HttpRequestMessage(HttpMethod.Post, "/api/asistente/preguntar");
        peticion.Headers.Add(FiltroIpRemota.Encabezado, ip);
        foreach (var (clave, valor) in encabezados ?? new Dictionary<string, string>())
        {
            peticion.Headers.TryAddWithoutValidation(clave, valor);
        }

        peticion.Content = new ByteArrayContent(Encoding.UTF8.GetBytes(cuerpo));
        if (tipoContenido is not null)
        {
            peticion.Content.Headers.TryAddWithoutValidation("Content-Type", tipoContenido);
        }

        using var respuesta = await cliente.SendAsync(peticion);
        var bytes = await respuesta.Content.ReadAsByteArrayAsync();
        return new RespuestaApi(respuesta.StatusCode, bytes, respuesta.Headers, respuesta.Content.Headers);
    }

    protected override void ConfigureWebHost(IWebHostBuilder builder)
    {
        builder.UseEnvironment("Production");
        builder.UseContentRoot(Path.Combine(DatosReferencia.RutaRepositorio(), "backend", "src", "TutorFlow.Api"));
        foreach (var (clave, valor) in _configuracion)
        {
            builder.UseSetting(clave, valor);
        }

        builder.ConfigureAppConfiguration((_, configuracion) => configuracion.AddInMemoryCollection(_configuracion));
        builder.ConfigureLogging(logging =>
        {
            logging.SetMinimumLevel(LogLevel.Trace);
            logging.AddProvider(Logs);
        });
        builder.ConfigureTestServices(Reemplazar);
    }

    private void Reemplazar(IServiceCollection servicios)
    {
        servicios.RemoveAll<IApiAcademica>();
        servicios.RemoveAll<IReloj>();
        if (_variablesEntorno is not null)
        {
            servicios.RemoveAll<IVariablesEntorno>();
            servicios.AddSingleton<IVariablesEntorno>(new VariablesEntornoFijas(_variablesEntorno));
        }

        servicios.AddSingleton<IApiAcademica>(Api);
        servicios.AddSingleton<IReloj>(Reloj);
        if (!_auditoriaReal)
        {
            servicios.RemoveAll<IAuditoria>();
            servicios.AddSingleton<IAuditoria>(Auditoria);
        }

        servicios.AddSingleton<Microsoft.AspNetCore.Hosting.IStartupFilter, FiltroIpRemota>();
        if (_conocimiento is not null)
        {
            servicios.RemoveAll<IBaseConocimiento>();
            servicios.AddSingleton(_conocimiento);
        }

        if (_manejadorHttp is not null)
        {
            servicios.ConfigureHttpClientDefaults(b => b.ConfigurePrimaryHttpMessageHandler(() => _manejadorHttp));
        }

        ReemplazarLlm(servicios);
    }

    private void ReemplazarLlm(IServiceCollection servicios)
    {
        if (!_reemplazarLlm)
        {
            return;
        }

