        Serializar(EsAnthropic(peticion)
            ? new
            {
                id = "msg_1",
                type = "message",
                role = "assistant",
                model = "m",
                content = new object[] { new { type = "text", text = texto } },
                stop_reason = "end_turn",
                usage = new { input_tokens = entrada, output_tokens = salida }
            }
            : new
            {
                id = "c1",
                @object = "chat.completion",
                choices = new object[] { new { index = 0, message = new { role = "assistant", content = texto, refusal = (string?)null }, finish_reason = "stop" } },
                usage = new { prompt_tokens = entrada, completion_tokens = salida, total_tokens = entrada + salida }
            });

    public static HttpResponseMessage LlamadaAHerramienta(PeticionLlm peticion, int entrada, int salida)
    {
        using var cuerpo = JsonDocument.Parse(peticion.Cuerpo);
        var primera = cuerpo.RootElement.GetProperty("tools")[0];
        return EsAnthropic(peticion)
            ? Serializar(new
            {
                id = "msg_2",
                type = "message",
                role = "assistant",
                model = "m",
                content = new object[] { new { type = "tool_use", id = "tu_1", name = primera.GetProperty("name").GetString(), input = new { } } },
                stop_reason = "tool_use",
                usage = new { input_tokens = entrada, output_tokens = salida }
            })
            : Serializar(new
            {
                id = "c2",
                @object = "chat.completion",
                choices = new object[]
                {
                    new
                    {
                        index = 0,
                        message = new
                        {
                            role = "assistant",
                            content = (string?)null,
                            tool_calls = new object[] { new { id = "call_1", type = "function", function = new { name = primera.GetProperty("function").GetProperty("name").GetString(), arguments = "{}" } } }
                        },
                        finish_reason = "tool_calls"
                    }
                },
                usage = new { prompt_tokens = entrada, completion_tokens = salida, total_tokens = entrada + salida }
            });
    }

    private static HttpResponseMessage Serializar(object valor) => Json(JsonSerializer.Serialize(valor));

    public static HttpResponseMessage Rechazo(PeticionLlm peticion) =>
        Json(EsAnthropic(peticion)
            ? """{"id":"msg_3","type":"message","role":"assistant","model":"m","content":[],"stop_reason":"refusal","usage":{"input_tokens":10,"output_tokens":0}}"""
            : """{"id":"c3","object":"chat.completion","choices":[{"index":0,"message":{"role":"assistant","content":null,"refusal":"No puedo ayudar con eso"},"finish_reason":"stop"}],"usage":{"prompt_tokens":10,"complet
}

