    };

    [GeneratedRegex(@"^\s*(\d+)\.\s+(.*)$", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex PasoNumerado();

    private static string Prompt(Rol rol) => ConstructorPrompts.PromptSistema(rol, MarcadorCanario);

    private static IReadOnlyList<string> Pasos(Rol rol)
    {
        var pasos = new List<string>();
        foreach (var linea in ConstructorPrompts.Instrucciones(Prompt(rol)).Split('\n').Select(l => l.TrimEnd('\r')))
        {
            var coincidencia = PasoNumerado().Match(linea);
            if (coincidencia.Success)
            {
                pasos.Add(coincidencia.Groups[2].Value);
            }
            else if (pasos.Count > 0 && linea.Trim().Length > 0 && !linea.TrimStart().StartsWith("Marcador", StringComparison.Ordinal))
            {
                pasos[^1] = $"{pasos[^1]} {linea.Trim()}";
            }
        }

        return pasos;
    }

    private static int Palabras(string texto) => texto.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries).Length;

