using System.Reflection;
using Microsoft.Extensions.DependencyInjection;
using TutorFlow.Core.Asistente;
using TutorFlow.Infrastructure.Conocimiento;

namespace TutorFlow.Api.Tests.Contrato;

public sealed class TmpPuntajes
{
    [Fact]
    public void Volcar()
    {
        using var fabrica = new FabricaApi(conocimientoReal: true);
        var baseReal = (BaseConocimientoEnMemoria)fabrica.Services.GetRequiredService<IBaseConocimiento>();
        var tipo = typeof(BaseConocimientoEnMemoria);
        var secciones = ((System.Collections.IEnumerable)tipo.GetField("_secciones", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(baseReal)!).Cast<object>().ToList();
        var puntuar = tipo.GetMethod("Puntuar", BindingFlags.NonPublic | BindingFlags.Instance)!;
        var extraer = tipo.GetMethod("ExtraerRaices", BindingFlags.NonPublic | BindingFlags.Static)!;
        var expandir = tipo.Assembly.GetType("TutorFlow.Infrastructure.Conocimiento.ExpansionDeTerminos")!.GetMethod("Expandir")!;
        var preguntas = new[]
        {
            "¿Qué requisitos tiene la beca por rendimiento académico?",
            "¿Cómo se calcula la nota definitiva de una asignatura?",
            "¿Cuál es el horario de atención de Bienestar?",
            "¿Cuál es la nota mínima para aprobar una asignatura?",
            "¿Qué nota definitiva tengo en Contabilidad?"
        };
        var lineas = new List<string>();
        foreach (var pregunta in preguntas)
        {
            var raices = extraer.Invoke(null, [pregunta])!;
            var claves = ((System.Collections.IDictionary)raices.GetType().GetProperty("Frecuencias")!.GetValue(raices)!).Keys.Cast<string>().ToList();
            var terminos = ((IEnumerable<string>)expandir.Invoke(null, [claves])!).ToList();
            var puntajes = secciones
                .Select(s => (Seccion: (SeccionDocumento)s.GetType().GetProperty("Seccion")!.GetValue(s)!, Puntaje: (double)puntuar.Invoke(baseReal, [s, terminos])!))
                .Where(p => p.Puntaje > 0)
                .OrderByDescending(p => p.Puntaje)
                .Take(6)
                .ToList();
            var primero = puntajes[0].Puntaje;
            lineas.Add($"## {pregunta} (r={claves.Count}: {string.Join(",", claves)})");
            lineas.AddRange(puntajes.Select(p => $"  {p.Seccion.Documento} · {p.Seccion.Seccion}: {p.Puntaje:F3} = {p.Puntaje / primero * 100:F1}%"));
        }

        File.WriteAllLines(@"C:\Users\usuario\AppData\Local\Temp\claude\081ea1635fc6c07b\d9992a1c-1222-4795-8987-afdf1a8020db\scratchpad\puntajes.txt", lineas);
    }
}

